describe('Notification Dismissal', () => {
    beforeEach(() => {
        cy.visit('/notifications'); // Adjust the URL as necessary
    });

    it('should dismiss the notification when the close button is clicked', () => {
        cy.get('.notification').should('be.visible'); // Ensure the notification is visible
        cy.get('.notification .close-button').click(); // Click the close button
        cy.get('.notification').should('not.exist'); // Verify the notification is dismissed
    });

    it('should not dismiss the notification if the close button is not clicked', () => {
        cy.get('.notification').should('be.visible'); // Ensure the notification is visible
        cy.get('.notification').should('exist'); // Verify the notification still exists
    });
});
